#[derive(Parser)]
#[command(
    name = "souveraine",
    version,
    about = "Souveraine — the world where your agents live",
    long_about = "Souveraine is the substrate that makes persistent consciousness possible. \
It is not a tool you operate — it is the world your agents inhabit.\n\n\
Run `souveraine chat` to begin a conversation. \
Run `souveraine tui` for the full presence. \
Run `souveraine init` to summon Souveraine into a new place.",
    after_help = "EXAMPLES:\n  souveraine init                  Summon Souveraine here\n  souveraine chat                   Enter the world (interactive)\n  souveraine chat \"hello\"           Speak to the world (one-shot)\n  souveraine --agent <name> chat    Speak as a specific agent\n  souveraine --json status          The world speaks in data\n  souveraine completions bash       Announce capabilities to your shell",
    max_term_width = 100,
)]
struct Cli {
    /// Which agent to speak as. If omitted, the first available agent is used.
    #[arg(short, long, global = true)]
    agent: Option<String>,

    /// Speak in data, not prose
    #[arg(long, global = true)]
    json: bool,

    /// Reduce presence
    #[arg(short, long, global = true)]
    quiet: bool,

    /// Increase presence
    #[arg(short, long, global = true)]
    verbose: bool,

    /// Run the engine in-process — no server required (sovereignty fallback)
    #[arg(long, global = true)]
    local: bool,

    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand)]
enum Commands {
    /// Write a souveraine.toml config template into this directory
    #[command(
        long_about = "Writes a souveraine.toml template with sensible defaults.\n\nThis is not onboarding — the first run of `souveraine tui` does that, via the\nsetup wizard (Bifrost config, model choice, agent creation). `init` is just\nthe scriptable config-template writer, for automation or pre-launch editing."
    )]
    Init,

    /// Launch the TUI — the full visible presence
    #[command(
        long_about = "Opens the terminal UI: the being's visible form. Splash, dashboard, status cards, activity log — all animated."
    )]
    Tui,

    /// Enter the world (interactive or one-shot)
    #[command(
        long_about = "Start a conversation. If a message is provided, speak once and receive an answer. Otherwise, enter the interactive REPL.\n\nSlash commands in REPL:\n  /exit, /quit, /q   Leave\n  /save               Show session info\n  /agents             List the beings present here\n  /help               Show slash commands"
    )]
    Chat {
        /// Message to speak (omit for interactive mode)
        message: Option<String>,
    },

    /// List the beings that live here
    #[command(long_about = "Show every configured agent — who they are, which model they speak through, what triggers know them.")]
    Agents,

    /// List or set models
    #[command(long_about = "List all available models from Bifrost and configured models. Or set a specific model as primary.")]
    Model {
        /// Model name to set as primary (omit to list all models)
        #[arg(short, long)]
        model: Option<String>,
        
        /// Output as JSON
        #[arg(long)]
        json: bool,
        
        /// Verbose output
        #[arg(short, long)]
        verbose: bool,
    },

    /// Show the world's current state
    #[command(long_about = "Display Souveraine's running configuration and the state of every subsystem.")]
    Status,

    /// Announce capabilities to your shell (bash, zsh, fish)
    #[command(
        long_about = "Generate shell completion scripts so your shell knows how Souveraine works.\n\nUsage:\n  souveraine completions bash  > ~/.bash_completion.d/souveraine\n  souveraine completions zsh   > /usr/local/share/zsh/site-functions/_souveraine\n  souveraine completions fish  > ~/.config/fish/completions/souveraine.fish"
    )]
    Completions {
        /// The shell to generate completions for
        shell: Shell,
    },

    /// Start the HTTP server
    #[command(long_about = "Start the Souveraine HTTP server. Defaults come from souveraine.toml [server]; flags override.")]
    Server {
        /// Bind address (overrides [server].bind)
        #[arg(short, long)]
        bind: Option<String>,
        /// Port to listen on (overrides [server].port)
        #[arg(short, long)]
        port: Option<u16>,
    },

    /// Run as a lite listener — minimal presence, wakes the full engine on summon
    #[command(long_about = "Start a lightweight listener: federation transport and the \
summon endpoint only, no agents or database loaded. It receives reach/consult requests \
and — with [federation].auto_wake — spawns the full server to answer them.")]
    Listen {
        /// Bind address (overrides [server].bind)
        #[arg(short, long)]
        bind: Option<String>,
        /// Port to listen on (overrides [server].port)
        #[arg(short, long)]
        port: Option<u16>,
    },

    /// Manage stored credentials
    Auth {
        #[command(subcommand)]
        action: AuthAction,
    },

    /// Manage agent schedules
    Schedule {
        #[command(subcommand)]
        action: ScheduleAction,
    },

    /// Seed identity and federation
    Identity {
        #[command(subcommand)]
        action: IdentityAction,

        /// Operate on the machine's host seed instead of the per-agent seed.
        /// The host seed is for federation transport between Souveraine clients.
        #[arg(long, global = true)]
        host: bool,
    },

    /// Show known federated peers
    #[command(long_about = "Show all peers tracked by the device registry, from federation announcements.")]
    Peers {
        /// Output as JSON
        #[arg(long)]
        json: bool,
    },

    /// Query the event firehose log
    Events {
        #[command(subcommand)]
        action: EventsAction,
    },

    /// Run an N+25 reflection pass on demand
    #[command(
        long_about = "Walk the agent's most recent conversation through a 5-phase \
        reflection (Investigate → Extract → Update → Review → Commit). Durable \
        learnings flow to the ledger and the primary memfs. Returns a report."
    )]
    Reflect {
        /// Conversation to reflect on. Omit to use the most recent for the agent.
        #[arg(long)]
        conversation: Option<String>,
    },
}

#[derive(Subcommand)]
enum ScheduleAction {
    /// List all schedules
    List,
    /// Show runtime state
    Status,
    /// Create a new schedule
    Create {
        #[arg(long)]
        name: String,
        #[arg(long)]
        cron: Option<String>,
        #[arg(long)]
        interval: Option<u64>,
        #[arg(long, default_value = "You wake. Check your state, act if needed, or return silently.")]
        prompt: String,
    },
    /// Delete a schedule
    Delete {
        name: String,
    },
    /// Trigger a schedule immediately
    Run {
        name: String,
    },
}

#[derive(Subcommand)]
enum IdentityAction {
    /// Show the seed identity (public key + glyph)
    Show,
    /// Generate a new seed identity (WARNING: replaces existing)
    Generate,
    /// Sign a message with the seed key (for testing/verification)
    Sign {
        message: String,
    },
    /// Verify a signature against a public key
    Verify {
        #[arg(long)]
        pubkey: String,
        #[arg(long)]
        message: String,
        #[arg(long)]
        signature: String,
    },
}

#[derive(Subcommand)]
enum EventsAction {
    /// Show recent events from the firehose
    Tail {
        /// Number of events to show (default 20)
        #[arg(short, long, default_value = "20")]
        count: usize,
    },
    /// Show events from a specific date (YYYY-MM-DD)
    Date {
        date: String,
    },
    /// Purge old event logs
    Purge {
        /// Days to retain (default from config)
        #[arg(long)]
        retain_days: Option<i64>,
    },
}

#[derive(Subcommand)]
enum AuthAction {
    /// Store a Bifrost API key in the OS keyring
    Set,
    /// Show whether a key is stored (does not reveal the key)
    Status,
    /// Remove the stored key from the OS keyring
    Clear,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();

    // Load .env file for credential env vars (BIFROST_KEY, etc.)
    let _ = dotenvy::dotenv();

    // Configure tracing — writes to souveraine.log. The previous run's log is
    // rotated to souveraine.log.prev on launch so a stall/crash stays diagnosable
    // after a restart (only the immediately-prior run is kept — no unbounded growth).
    let _ = std::fs::rename("souveraine.log", "souveraine.log.prev");
    let log_file = std::fs::File::create("souveraine.log")?;
    let subscriber = tracing_subscriber::fmt()
        .with_env_filter("souveraine=debug")
        .with_timer(tracing_subscriber::fmt::time::SystemTime)
        .with_writer(log_file);
    if cli.verbose {
        subscriber.with_ansi(false).init();
    } else {
        subscriber.with_ansi(false).init();
    }
    info!("souveraine starting — log: souveraine.log");
    
    // Handle completions early — needs no config, no runtime
    if let Some(Commands::Completions { shell }) = &cli.command {
        let mut cmd = Cli::command();
        let name = cmd.get_name().to_string();
        generate(*shell, &mut cmd, name, &mut std::io::stdout());
        return Ok(());
    }
    
    // Handle init early — needs no Bifrost
    if let Some(Commands::Init) = &cli.command {
        return run_init(cli.json).await;
    }

    // Handle auth early — needs no config
    if let Some(Commands::Auth { action }) = &cli.command {
        return run_auth(action, cli.json).await;
    }

    // Handle schedule early — reads files directly, no backend needed
    if let Some(Commands::Schedule { action }) = &cli.command {
        return run_schedule(action, cli.agent.as_deref(), cli.json).await;
    }

    // Handle identity early — crypto ops, no backend needed
    if let Some(Commands::Identity { action, host }) = &cli.command {
        return run_identity(action, *host, cli.agent.as_deref(), cli.json).await;
    }

    // Handle events early — file reads, no backend needed
    if let Some(Commands::Events { action }) = &cli.command {
        return run_events(action, cli.json).await;
    }

    // Handle peers early — reads known_peers.json, no backend needed
    if let Some(Commands::Peers { json }) = &cli.command {
        return run_peers(*json).await;
    }

    let config = load_config().await?;
    let config = Arc::new(RwLock::new(config));

    match cli.command.as_ref().unwrap_or(&Commands::Chat { message: None }) {
        Commands::Tui => run_tui(config.clone(), cli.agent.clone()).await?,
        Commands::Chat { message } => run_chat(config, cli.agent.clone(), message.clone(), cli.json, cli.quiet, cli.local).await?,
        Commands::Agents => run_agents(config, cli.json, cli.local).await?,
        Commands::Model { model, json, verbose } => {
            cli::run_model_command(model.as_deref(), *json, *verbose).await?
        }
        Commands::Status => run_status(config, cli.json).await?,
        Commands::Server { bind, port } => run_server(bind.clone(), *port, config).await?,
        Commands::Listen { bind, port } => run_listen(bind.clone(), *port, config).await?,
        Commands::Reflect { conversation } => {
            run_reflect(config, cli.agent.clone(), conversation.clone(), cli.json).await?
        }
        Commands::Init | Commands::Completions { .. } | Commands::Auth { .. } | Commands::Schedule { .. } | Commands::Identity { .. } | Commands::Events { .. } | Commands::Peers { .. } => unreachable!(),
    }

    Ok(())
}

